return $input.all().map(i => {
  const row = i.json;
  let brief = row.raw_payload;
  if (typeof brief === 'string') { try { brief = JSON.parse(brief); } catch(e){ brief = null; } }
  if (!brief || typeof brief !== 'object') {
    brief = { meta:{ engine:'WHEN Layer Intelligence Engine', document_type:'account brief', schema_version:'1.1', export_date:new Date().toISOString().slice(0,10) }, account:{ name: row.account || 'unknown' }, signals:[], buying_group:[], human_signals:[] };
  }
  brief.human_signals = Array.isArray(brief.human_signals) ? brief.human_signals : [];
  let sigs = row.signals; if (typeof sigs === 'string') { try { sigs = JSON.parse(sigs); } catch(e){ sigs = []; } }
  if (!Array.isArray(sigs)) sigs = [];
  for (const s of sigs) brief.human_signals.push({ type:'engagement', signal: s.signal, occurred_at: s.occurred_at, value: s.value, source:'delivery_layer' });
  return { json: { account: row.account, when_engine_url: row.when_engine_url || '', payload: brief } };
});
